package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	n := nextInt(scanner)
	m := nextInt(scanner)

	foods := make(map[int]int)
	for i := 0; i < m; i++ {
		food := nextInt(scanner)
		foods[food]++
	}

	left := 0
	right := m / n
	for left < right {
		mid := (left + right + 1) / 2
		if canSurvive(mid, n, foods) {
			left = mid
		} else {
			right = mid - 1
		}
	}
	fmt.Println(left)
}

func nextInt(scanner *bufio.Scanner) int {
	scanner.Scan()
	var x int
	fmt.Sscan(scanner.Text(), &x)
	return x
}

func canSurvive(day int, people int, foods map[int]int) bool {
	if day == 0 {
		return true
	}
	sumPeople := 0
	for _, count := range foods {
		sumPeople += count / day
	}
	return sumPeople >= people
}

