    var left = 0
    var right = m / n
    while (left < right) {
        val mid = (left + right + 1) / 2
        val canSurviveMid = canSurvive(mid, n, foods)
        if (canSurviveMid) {
            left = mid
        } else {
            right = mid - 1
        }
    }
    println(left)
